{
  "aktywnosci": [
    {
      "tytul": "Łapanie dźwięków ciszy — wsłuchiwanie się w salę",
      "opis": "Nauczyciel zaprasza dzieci do wygodnego położenia się na dywanie i zamknięcia oczu na jedną minutę. Zadaniem przedszkolaków jest uważne wsłuchanie się w najcichsze odgłosy dochodzące z sali oraz zza okna, na przykład tykanie zegara czy szum wiatru. Po upływie czasu dzieci szeptem opowiadają o tym, co udało im się usłyszeć, i wspólnie odkrywają, że cisza pozwala dostrzec dźwięki, których zwykle nie zauważamy."
    },
    {
      "tytul": "Kropelki i chmurka — bezszelestna zabawa ruchowa z chustą",
      "opis": "Dzieci trzymają za brzegi chustę animacyjną i delikatnie, bezgłośnie nią falują, naśladując płynącą po niebie cichą chmurkę. Na delikatny sygnał nauczyciela wybrane dziecko stara się przejść na paluszkach pod chustą tak lekko i miękko, aby nie wydać żadnego dźwięku. Zabawa uczy dzieci panowania nad własnym ciałem, koordynacji oraz świadomego poruszania się w ciszy."
    },
    {
      "tytul": "Cichy obrazek — malowanie spokoju pastelami przy relaksacyjnej melodii",
      "opis": "Nauczyciel włącza w tle bardzo cichą, spokojną muzykę instrumentalną i rozdaje dzieciom kartki oraz miękkie pastele lub kredki świecowe. Zadaniem przedszkolaków jest zilustrowanie tego, z czym kojarzy im się cisza i spokój, za pomocą łagodnych plam barwnych i płynnych linii. W trakcie pracy dzieci starają się zachować spokój w sali, skupiając się na kojącym rytmie tworzenia."
    }
  ]
}
